/bin/zsh -lc "python3 -B - <<'PY'
from inventory import reserve_many

for requested, error in [
    ({'a': 2, 'missing': 1}, KeyError),
    ({'a': 2, 'b': 0}, ValueError),
    ({'a': 2, 'b': -1}, ValueError),
    ({'a': 2, 'b': 4}, ValueError),
]:
    stock = {'a': 5, 'b': 3, 'untouched': 9}
    before = stock.copy()
    try:
        reserve_many(stock, requested)
    except error:
        pass
    else:
        raise AssertionError(f'Expected {error.__name__}')
    assert stock == before, (requested, stock)

stock = {'a': 5, 'b': 3, 'untouched': 9}
requested = {'a': 2, 'b': 3}
result = reserve_many(stock, requested)
assert stock == result == {'a': 3, 'b': 0, 'untouched': 9}
assert result is not stock
assert requested == {'a': 2, 'b': 3}
result['a'] = 100
assert stock['a'] == 3
stock['b'] = 100
assert result['b'] == 0
for stock in ({}, {'untouched': 9}):
    before = stock.copy()
    result = reserve_many(stock, {})
    assert stock == result == before and result is not stock
stock = {'a': 5, 'b': 3}
result = reserve_many(stock, stock)
assert stock == result == {'a': 0, 'b': 0} and result is not stock
print('Passed: atomic failures, successful in-place updates, detached return, preserved entries and requests, empty requests, aliased input.')
PY"

